class Solution:

    """
    Problem: https://leetcode.com/problems/count-collisions-on-a-road/
    Difficulty: medium
    Solution successful: yes

    Solution: for speed, the moving cars should be treated as caravans, if they're together in a line.
    If a caravan of three cars going right hits a caravan of seven cars going left, that's seven
    collisions.

    We go through the left-traveling caravans, starting with the leftmost, and eliminate them one-by-one,
    finding collisions or removing the cars.

    Same idea with the right-traveling ones, but starting from the right.
    """

    debug = False

    def countCollisions(self, directions: str) -> int:
        # Maps a float x to number of collisions there
        collision_array = [0] * len(directions) * 2

        self.print(f"Original directions: {directions}")
        left_caravan_array = [0] * len(directions)
        caravan_size = 0
        for x in range(len(directions)-1, -1, -1):
            if directions[x] == "L":
                caravan_size += 1
            else:
                if caravan_size > 0:
                    left_caravan_array[x+1] = caravan_size
                    caravan_size = 0
        self.print(f"Left caravan array {left_caravan_array}")

        right_caravan_array = [0] * len(directions)
        caravan_size = 0
        for x in range(len(directions)):
            if directions[x] == "R":
                caravan_size += 1
            else:
                if caravan_size > 0:
                    right_caravan_array[x-1] = caravan_size
                    caravan_size = 0
        self.print(f"Right caravan array {right_caravan_array}")

        stationary_array = [1 if direction == "S" else 0 for direction in directions]

        # Deal with cars going left
        for pos in range(len(directions)):
            caravan_size = left_caravan_array[pos]
            if caravan_size == 0:
                continue

            locations_str, collisions_str = self.maps_to_str(left_caravan_array, right_caravan_array, stationary_array, collision_array)
            self.print(f"Evaluating caravan at {pos} ({directions[pos]}, {caravan_size}):")
            self.print(locations_str)
            self.print(collisions_str)

            # Going left, might hit a stationary car, a caravan going right, or a pileup
            hit_something = False
            for x in range(pos-1, -1, -1):
                right_caravan_size = right_caravan_array[x]
                stationary_car_count = stationary_array[x]

                if stationary_car_count > 0:
                    # This caravan hits a stationary car
                    stationary_array[x] = 0
                    collision_array[int(x * 2)] += caravan_size
                    break
                elif right_caravan_size > 0:
                    # This car hits a caravan going right
                    x_halfway = float((x + pos) / 2)
                    right_caravan_array[x] = 0
                    collision_array[int(x_halfway * 2)] += caravan_size + right_caravan_size
                    break

                wreck_x_pts = [float(x)+0.5, float(x)]
                for wreck_x in wreck_x_pts:
                    collision_count = collision_array[int(wreck_x * 2)]
                    if collision_count > 0:
                        collision_array[int(x * 2)] += caravan_size
                        hit_something = True
                        break
                if hit_something:
                    break

            # Just remove the caravan
            left_caravan_array[pos] = 0

        # Deal with caravans going right
        for pos in range(len(directions) - 1, -1, -1):
            caravan_size = right_caravan_array[pos]
            if caravan_size == 0:
                continue

            locations_str, collisions_str = self.maps_to_str(left_caravan_array, right_caravan_array, stationary_array, collision_array)
            self.print(f"Evaluating caravan at {pos} ({directions[pos]}, {caravan_size}):")
            self.print(locations_str)
            self.print(collisions_str)

            # Going right, might hit some other car
            hit_something = False
            for x in range(pos + 1, len(directions)):
                stationary_car_count = stationary_array[x]

                if stationary_car_count > 0:
                    # This caravan hits a stationary car
                    stationary_array[x] = 0
                    collision_array[int(x * 2)] += caravan_size
                    break

                # Did the car hit a wreck?
                wreck_x_pts = [float(x) - 0.5, float(x)]
                for wreck_x in wreck_x_pts:
                    collision_count = collision_array[int(wreck_x * 2)]
                    if collision_count > 0:
                        collision_array[int(x * 2)] += caravan_size
                        hit_something = True
                        break
                if hit_something:
                    break

            # Just remove the caravan
            right_caravan_array[pos] = 0

        locations_str, collisions_str = self.maps_to_str(left_caravan_array, right_caravan_array, stationary_array, collision_array)
        self.print("Final maps")
        self.print(locations_str)
        self.print(collisions_str)

        total_collisions = sum(collision_array)

        return total_collisions

    def maps_to_str(self, left_caravan_array, right_caravan_array, stationary_array, collision_array):
        if not self.debug:
            return "", ""

        locations_array = [" "] * len(left_caravan_array)
        for j in range(len(left_caravan_array)):
            if left_caravan_array[j] > 0:
                for i in range(left_caravan_array[j]):
                    locations_array[j+i] = "L"
        for j in range(len(right_caravan_array)-1, -1, -1):
            if right_caravan_array[j] > 0:
                for i in range(right_caravan_array[j]):
                    locations_array[j-i] = "R"
        for j in range(len(stationary_array)):
            if stationary_array[j] > 0:
                locations_array[j] = "S"

        locations_str = " ".join(locations_array)

        collisions_str = ""
        for xx in range(len(left_caravan_array) * 2):
            count = collision_array[xx]
            collisions_str += "*" if count > 9 else (f"{count}" if count > 0 else " ")
        return locations_str, collisions_str

    def print(self, s):
        if self.debug:
            print(s)


